# -*- coding: utf-8 -*-
"""Reproducible source for the two standalone BI gallery demos."""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parents[3]
LANG={}
def t(en,ru,tag='span',attrs=''):
    key=str(len(LANG));LANG[key]={'en':en,'ru':ru}
    return f'<{tag} data-i18n="{key}" {attrs}>{en}</{tag}>'
def button(en,ru,attrs=''):
    return t(en,ru,'button',attrs)
def arrow():return '<span class="arrow" aria-hidden="true">↗</span>'
def logo(name):
    return f'<a class="brand" href="#top" aria-label="{name} home"><svg viewBox="0 0 28 28" width="26" height="26" aria-hidden="true"><path d="M3 21 10 6l5 10 4-8 6 13M3 25h22" fill="none" stroke="currentColor" stroke-width="2.3"/></svg>{name}<sup>BI</sup></a>'

