COMMON_JS=r'''
const $=(s,p=document)=>p.querySelector(s), $$=(s,p=document)=>[...p.querySelectorAll(s)];
const media=matchMedia('(prefers-reduced-motion: reduce)');let paused=false;const active=new Set();const finishes=new Map();
const reduce=()=>media.matches||paused;
function motion(el,frames,options={}){if(!el||reduce())return null;const a=el.animate(frames,{duration:650,easing:'cubic-bezier(.16,1,.3,1)',...options});active.add(a);a.finished.then(()=>active.delete(a)).catch(()=>active.delete(a));return a;}
function number(el,end,formatter=v=>v.toFixed(1),duration=1000){if(!el)return;finishes.get(el)?.();const final=()=>{cancelAnimationFrame(raf);el.textContent=formatter(end);finishes.delete(el)};let raf=0;if(reduce()){final();return}let start=performance.now();finishes.set(el,final);function tick(now){const p=Math.min(1,(now-start)/duration);el.textContent=formatter(end*(1-Math.pow(1-p,3))); if(p<1)raf=requestAnimationFrame(tick);else finishes.delete(el)}raf=requestAnimationFrame(tick)}
function stopMotion(){if(reduce()){active.forEach(a=>a.cancel());finishes.forEach(f=>f());}document.body.classList.toggle('motion-paused',reduce());}
media.addEventListener('change',stopMotion);document.addEventListener('visibilitychange',()=>{document.body.classList.toggle('page-hidden',document.hidden);if(document.hidden){active.forEach(a=>a.cancel());finishes.forEach(f=>f())}});
const words=__DICTIONARY__;let lang='en';
function apply(next){lang=next;document.documentElement.lang=lang;document.documentElement.dataset.lang=lang;$$('[data-i18n]').forEach(el=>{el.innerHTML=words[el.dataset.i18n][lang]});$$('[data-set]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.set===lang)));$$('[data-placeholder-en]').forEach(el=>el.placeholder=el.getAttribute('data-placeholder-'+lang));$$('[data-label-en]').forEach(el=>el.setAttribute('aria-label',el.getAttribute('data-label-'+lang)));updateMotionLabel();window.refreshLanguage?.();}
function updateMotionLabel(){const b=$('[data-pause]');if(b){b.textContent=lang==='ru'?(paused?'▶ Анимации':'Ⅱ Пауза анимаций'):(paused?'▶ Play motion':'Ⅱ Pause motion');b.setAttribute('aria-pressed',String(paused))}}
$$('[data-set]').forEach(b=>b.addEventListener('click',()=>apply(b.dataset.set)));$$('[data-pause]').forEach(b=>b.addEventListener('click',()=>{paused=!paused;stopMotion();updateMotionLabel()}));
const zones=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('in-view',e.isIntersecting)),{threshold:.01});$$('.motion-zone').forEach(el=>zones.observe(el));
const reveal=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)return;const el=e.target;const originalTransform=getComputedStyle(el).transform;const finalTransform=originalTransform==='none'?'translateY(0)':originalTransform;motion(el,[{opacity:0,transform:'translateY(26px) '+(originalTransform==='none'?'':originalTransform)},{opacity:1,transform:finalTransform}],{delay:Number(el.dataset.delay||0),duration:800});el.dataset.revealed='true';reveal.unobserve(el);$$('[data-count]',el).forEach(n=>number(n,Number(n.dataset.count),v=>v.toFixed(Number(n.dataset.decimals||0))));$$('.draw',el).forEach(path=>{const n=path.getTotalLength();motion(path,[{strokeDasharray:n,strokeDashoffset:n},{strokeDasharray:n,strokeDashoffset:0}],{duration:1300,delay:250})});$$('.alert-row',el).forEach((row,i)=>motion(row,[{opacity:0,transform:'translateX(14px)'},{opacity:1,transform:'translateX(0)'}],{duration:650,delay:180+i*130}));$$('.speed-line span',el).forEach((bar,i)=>motion(bar,[{transform:'scaleX(0)'},{transform:'scaleX(1)'}],{duration:900,delay:250+i*200}));$$('.scatter i',el).forEach((dot,i)=>motion(dot,[{opacity:0,transform:'scale(0)'},{opacity:.7,transform:'scale(1)'}],{duration:700,delay:150+(i%12)*30}));$$('.bar',el).forEach((b,i)=>motion(b,[{transform:'scaleY(0)'},{transform:'scaleY(1)'}],{duration:950,delay:i*40}));}),{threshold:.12});$$('[data-reveal]').forEach(el=>reveal.observe(el));
$$('.nav-menu').forEach(menu=>{menu.addEventListener('pointerenter',()=>{menu.open=true;motion($('.menu-panel',menu),[{opacity:0,transform:'translateY(-8px)'},{opacity:1,transform:'translateY(0)'}],{duration:200})});menu.addEventListener('pointerleave',()=>{if(!menu.contains(document.activeElement))menu.open=false});menu.addEventListener('focusout',e=>{if(!menu.contains(e.relatedTarget))menu.open=false});menu.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.open=false;$('summary',menu).focus()}});$$('a',menu).forEach(a=>a.addEventListener('click',()=>menu.open=false));});
$$('.faq details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)motion($('p',d),[{opacity:0,transform:'translateY(-8px)'},{opacity:1,transform:'translateY(0)'}],{duration:350})}));
const modal=$('#walkthrough');$$('[data-open-modal]').forEach(b=>b.addEventListener('click',()=>{modal.showModal();motion(modal,[{opacity:0,transform:'translateY(18px) scale(.97)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:300})}));$$('[data-close-modal]').forEach(b=>b.addEventListener('click',()=>modal.close()));modal?.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
let scrollQueued=false;function progress(){scrollQueued=false;const h=document.documentElement.scrollHeight-innerHeight;$('.progress').style.transform='scaleX('+(h>0?scrollY/h:0)+')'}addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(progress)}},{passive:true});
function exportCsv(name,rows){const blob=new Blob(['\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);const status=$('[data-export-status]');if(status)status.textContent=lang==='ru'?'CSV выгружен · демонстрационные данные':'CSV exported · sample data';}
$$('a[href^="#"]').forEach(a=>a.addEventListener('click',e=>{const target=$(a.getAttribute('href'));if(target){e.preventDefault();target.scrollIntoView({behavior:reduce()?'instant':'smooth',block:'start'});history.replaceState(null,'',a.getAttribute('href'));}}));
stopMotion();updateMotionLabel();
'''

def lang_control():
    return '<div class="lang" role="group" aria-label="Language"><button data-set="en" aria-pressed="true">EN</button><span>/</span><button data-set="ru" aria-pressed="false">RU</button></div>'
def modal(name):
    return f'''<dialog class="modal" id="walkthrough" aria-labelledby="modal-title">{button('×','×','class="close" data-close-modal aria-label="Close"')}<div class="eyebrow">{name} / {t('Interactive product tour','Интерактивный обзор')}</div>{t('A clearer view of your business.','Новый взгляд на ваш бизнес.','h2','id="modal-title"')}{t('Explore the sample workspace. Every chart uses a small, local dataset, so you can try the controls without connecting an account.','Изучите демопространство. Графики используют локальный набор данных — попробуйте управление без подключения аккаунта.','p')}<ol><li>{t('Change a period or a data view.','Выберите период или представление данных.')}</li><li>{t('Hover a chart to inspect its values.','Наведите на график, чтобы увидеть значения.')}</li><li>{t('Export the sample data as a CSV file.','Выгрузите демонстрационные данные в CSV.')}</li></ol><form method="dialog">{button('Let’s explore →','Перейти к демо →','class="btn"')}</form></dialog>'''

